# Finance Hub, part A: money and banking, budgeting, saving and investing, markets and the economy, credit.
# Each sub-topic: the PIs it covers, an in-depth explanation, how it works, key numbers (with sources),
# real-world examples, exam/roleplay traps, a line to say, and judge questions with strong answers
# (Answer -> Reason -> Example -> Tie back). Time-sensitive numbers say "as of" and were checked Nov 2026.
H = []
def topic(id, title, areas, blurb):
    H.append(dict(id=id, title=title, areas=areas, blurb=blurb, subs=[]))
def sub(id, title, pis, what, how, nums, real, traps, say, qs, learn=()):
    H[-1]['subs'].append(dict(id=id, title=title, pis=pis, what=what, how=how, nums=nums, real=real, traps=traps,
                              say=say, qs=[dict(q=q, a=a) for q, a in qs], learn=[list(x) for x in learn]))

FDIC = ["FDIC", "https://www.fdic.gov"]; NCUA = ["NCUA (credit unions)", "https://mycreditunion.gov"]
FED = ["Federal Reserve", "https://www.federalreserve.gov"]; CFPB = ["CFPB", "https://www.consumerfinance.gov"]
INV = ["SEC Investor.gov", "https://www.investor.gov"]; FINRA = ["FINRA", "https://www.finra.org"]
BLS = ["BLS (inflation and jobs)", "https://www.bls.gov"]; BEA = ["BEA (GDP)", "https://www.bea.gov"]
IRS = ["IRS", "https://www.irs.gov"]; EDGAR = ["SEC EDGAR filings", "https://www.sec.gov/edgar"]
NYFED = ["New York Fed household debt report", "https://www.newyorkfed.org/microeconomics/hhdc"]
ACR = ["AnnualCreditReport.com (the only official free site)", "https://www.annualcreditreport.com"]
FRH = ["Federal Reserve History", "https://www.federalreservehistory.org"]; SIPC = ["SIPC", "https://www.sipc.org"]
NACHA = ["Nacha (ACH network)", "https://www.nacha.org"]; NGPF = ["Next Gen Personal Finance", "https://www.ngpf.org"]

# =====================================================================
topic("banking", "Money, banks & payments", ["Financial Analysis"],
      "What money is, how banks really make money, who provides financial services, how deposits are protected and how payments move.")

sub("money-basics", "What money is and the forms it takes", ["FI:058", "FI:059", "FI:060"],
    ["Money is anything people widely accept in exchange for goods and services. It does three jobs: a medium of exchange (you trade it instead of bartering), a unit of account or measure of value (prices are stated in it, so you can compare a $4 latte to a $40 shirt), and a store of value (you can hold it and spend it later). Inflation weakens the third job, which is why advisors say cash is for safety, not growth.",
     "Today's U.S. dollar is fiat money: it has value because the government declares it legal tender and people trust it, not because it can be swapped for gold. Physical currency is a small share of the money supply. Most money is just bank-account balances that move electronically, which is why forms of exchange like debit cards, ACH transfers and mobile payments matter more every year."],
    ["Good money is durable, portable, divisible, uniform, limited in supply and widely accepted.",
     "Currency types: coins (U.S. Mint), paper Federal Reserve notes (printed by the Bureau of Engraving and Printing), and government IOUs like Treasury bills, notes and bonds.",
     "Forms of exchange: cash, checks, debit cards (money leaves your account now), credit cards (you borrow and pay later), electronic funds transfers such as ACH and wires, mobile wallets and peer-to-peer apps.",
     "Barter fails because it needs a 'double coincidence of wants': both sides must want exactly what the other has.",
     "Cryptocurrency works as a medium of exchange for some, but its price swings make it a weak unit of account and store of value."],
    ["Cash was used for about 14% of U.S. consumer payments in 2024, down from about 31% in 2016 (Federal Reserve Diary of Consumer Payment Choice).",
     "The U.S. Mint struck its last pennies for circulation in November 2025; each one cost about 3.7 cents to make (U.S. Treasury and U.S. Mint).",
     "The U.S. ended the domestic gold standard in 1933 and ended gold convertibility for foreign governments in 1971 (Federal Reserve History)."],
    ["A 2025 executive order directed federal agencies to phase out paper checks for most federal payments starting September 30, 2025, moving benefits and refunds to direct deposit and other electronic payments (U.S. Treasury).",
     "Venezuela and Zimbabwe show what happens when a currency loses its store-of-value job: hyperinflation pushed people to use U.S. dollars instead."],
    ["Debit is your money; credit is borrowed money. Exams often swap them.", "A Treasury bond is a form of currency in the DECA PI list's sense (a government IOU), even though you can't spend it at a store."],
    "\"Money has three jobs: to spend, to price things and to store value. Cash in a checking account does the first two well but loses ground on the third every year inflation runs above zero.\"",
    [("Why shouldn't our client keep all of their savings in cash?",
      "Because cash is great for safety but poor at storing value over time. With inflation at about 3.7% in September 2026, $10,000 in a 0% account buys roughly $370 less a year later. We'd keep three to six months of expenses in an insured high-yield savings account for emergencies and invest money for goals five or more years away, so it can outgrow inflation. That way the client is safe now and still building wealth."),
     ("Is cryptocurrency real money?",
      "It does some of money's jobs, but not all of them well. People can use it to pay, so it's a medium of exchange, but its price can swing 10% in a day, so it fails as a stable unit of account or store of value. Bitcoin fell about 64% in 2022, for example. If a client wants exposure, we'd cap it at a small slice they can afford to lose and keep their emergency fund in FDIC-insured dollars.")],
    [FED, FRH])

sub("bank-how", "How banks make money and how the Fed fits in", ["FI:336"],
    ["A bank is a middleman between savers and borrowers. It pays depositors interest, lends that money out at a higher rate, and keeps the difference, called the net interest margin. Banks also earn fee income from things like overdrafts, wire transfers, card interchange, wealth management and loan origination. A deposit is a liability for the bank (it owes you the money), and a loan is an asset (the borrower owes the bank).",
     "Because banks lend out most deposits, they hold only a fraction in cash and reserves. This fractional-reserve system creates money: when a bank lends, the borrower's new account balance is new money in the economy. It also makes banks vulnerable to runs, which is why we have deposit insurance, capital rules and the Federal Reserve as lender of last resort. The Fed is the central bank: a Board of Governors in Washington, 12 regional Reserve Banks and the Federal Open Market Committee, which sets interest-rate policy."],
    ["Financial institutions perform intermediation: they pool savings, judge borrowers' credit, spread risk and make money liquid.",
     "Banks are chartered by the federal government (supervised by the OCC) or a state, and are also overseen by the Fed and the FDIC.",
     "Capital (the owners' money) absorbs losses before depositors do; regulators require minimum capital ratios under the Basel III framework.",
     "The Fed's tools: the interest rate it pays on banks' reserves, open market operations (buying and selling Treasuries), and the discount window, where banks borrow in an emergency.",
     "Reserve requirements have been 0% since March 2020, so today the Fed steers rates with interest on reserves rather than required reserves."],
    ["There were 4,238 FDIC-insured institutions in the second quarter of 2026, down from more than 17,000 in 1984 (FDIC Quarterly Banking Profile and historical statistics).",
     "U.S. banks earned $90.1 billion in net income in the second quarter of 2026 (FDIC Quarterly Banking Profile).",
     "The prime rate is set at the top of the Fed's target range plus 3 points, so with the Fed at 3.75%-4.00% (Oct. 2026), prime is 7.00%."],
    ["Silicon Valley Bank failed in March 2023 after depositors pulled $42 billion in a single day; it had invested heavily in long-term bonds that lost value when rates rose (Federal Reserve review of SVB).",
     "In 2008 the Fed lent hundreds of billions to banks and markets as lender of last resort, and Congress passed the $700 billion TARP program (Federal Reserve History)."],
    ["A deposit is the bank's liability, not its asset.", "The Fed doesn't set your mortgage rate directly; it sets a short-term target that ripples out to other rates."],
    "\"Your deposit doesn't sit in a vault. The bank lends it out and earns the spread, which is why it can pay you interest, and why the FDIC insures you up to $250,000 if something goes wrong.\"",
    [("How does a bank actually make money off our deposits?",
      "Mostly from the spread. It pays depositors one rate, lends at a higher one, and keeps the difference. If a bank pays 2% on savings and charges 7% on a car loan, the 5-point gap covers its costs and profit. It also earns fees, from cards and wires to wealth management. That's why we'd steer you to a bank paying a competitive rate, so more of that spread stays with you."),
     ("What role does the Federal Reserve play in our client's day-to-day finances?",
      "The Fed sets the short-term interest rate that other rates key off. When the Fed raised rates in 2022 and 2023, credit card APRs climbed above 20% and savings yields rose above 4%. Its September 2026 hike to 3.75%-4.00% does the same thing on a smaller scale. For our client, that means paying down variable-rate debt first and locking in today's higher savings yields with a CD."),
     ("Why do banks fail if they're so regulated?",
      "Usually because they take on a risk that hits all at once. Silicon Valley Bank put deposits into long-term bonds, rates rose, the bonds lost value, and when depositors panicked it couldn't pay. Regulation lowers the odds but can't remove them. That's why we spread large balances so each bank holds no more than the $250,000 FDIC limit.")],
    [FED, FDIC, FRH])

sub("providers", "Types of financial-services providers and how to choose one", ["FI:075", "FI:076"],
    ["Financial-services providers fall into a few families. Depository institutions take deposits and make loans: commercial banks (owned by shareholders, for profit), savings institutions or thrifts (historically focused on mortgages) and credit unions (not-for-profit cooperatives owned by members, often with lower fees and loan rates). Non-depository institutions don't take insured deposits: brokerage firms, investment banks, mutual fund companies, insurance companies, pension funds, finance companies and fintech apps.",
     "There are also alternative providers such as payday lenders, check cashers, pawnshops and rent-to-own stores. They serve people with little or no bank access but charge very high effective rates. Choosing a provider means matching the client's needs (convenience, products, advice) against safety (is it insured and regulated?), cost (fees, interest rates) and trust (reputation, customer service, technology)."],
    ["Commercial bank: checking, savings, loans, cards, business banking; FDIC-insured.",
     "Credit union: same basic services, NCUA-insured, membership based on employer, location or group; profits return to members as better rates.",
     "Brokerage: buys and sells securities; protected by SIPC against firm failure, not market losses.",
     "Insurance company: pools risk through premiums; regulated by state insurance departments.",
     "Fintech or neobank (Chime, Cash App, PayPal): usually partners with a chartered bank, which holds the money and provides the FDIC coverage.",
     "Selection checklist: insured? fees? rates? ATM and branch access? app quality? services you'll need later (mortgage, investing)? complaints record?"],
    ["About 4.2% of U.S. households (5.6 million) had no bank account in 2023; the most common reason was not having enough money to meet minimum balances (FDIC National Survey of Unbanked and Underbanked Households).",
     "Federally insured credit unions serve more than 140 million members (NCUA).",
     "A typical two-week payday loan fee of $15 per $100 borrowed equals an APR of almost 400% (CFPB)."],
    ["Big banks like JPMorgan Chase offer one-stop shopping (checking, mortgages, investing through J.P. Morgan Wealth Management), while online banks like Ally offer higher savings rates with no branches.",
     "Navy Federal Credit Union, the largest U.S. credit union, serves military members and their families."],
    ["A credit union is not-for-profit and member-owned; a savings and loan can be either mutual or stock-owned.", "Brokerage accounts are covered by SIPC, not FDIC."],
    "\"We'd match the provider to the need: an insured high-yield online bank for savings, a low-cost brokerage for investing, and a credit union if you want lower rates on a car loan.\"",
    [("Should our client use a bank or a credit union?",
      "It depends on what they value, but for most young clients a credit union is worth a look. Because it's member-owned and not-for-profit, it often charges lower loan rates and fewer fees, and deposits are insured by the NCUA up to $250,000, just like FDIC coverage at a bank. A big bank wins on nationwide ATMs, apps and one-stop services. We'd suggest checking at the credit union for a cheaper car loan, plus a high-yield online savings account for the emergency fund."),
     ("Why not just use a payday loan in an emergency?",
      "Because it's one of the most expensive forms of credit there is. The CFPB says a typical $15 fee per $100 for two weeks is an APR near 400%, and many borrowers roll the loan over again and again. A credit union small-dollar loan, a 0% payment plan with the provider, or the emergency fund we're building are far cheaper. Building that fund is how we keep the client from ever needing a payday lender.")],
    [FDIC, NCUA, CFPB])

sub("deposit-safety", "Deposit insurance and keeping money safe", ["FI:336", "FI:075"],
    ["Deposit insurance protects depositors if a bank or credit union fails. The FDIC, created by the Banking Act of 1933 after thousands of banks failed in the Great Depression, insures deposits up to $250,000 per depositor, per insured bank, per ownership category. The NCUA provides the same coverage at federally insured credit unions. Since the FDIC began in 1934, no depositor has lost a penny of insured funds.",
     "The key phrase is 'per ownership category.' Single accounts, joint accounts, certain retirement accounts and trust accounts each get separate coverage, so a married couple can insure far more than $250,000 at one bank by titling accounts correctly. Investments are different: stocks, bonds, mutual funds, annuities and crypto are not FDIC-insured even if you buy them at a bank. At a brokerage, SIPC protects up to $500,000 (including $250,000 cash) if the firm fails, but never protects against market losses."],
    ["Covered: checking, savings, money market deposit accounts, CDs.",
     "Not covered: stocks, bonds, mutual funds, ETFs, annuities, life insurance, crypto, safe deposit box contents.",
     "Joint accounts: $250,000 per co-owner, so $500,000 for a couple's joint account.",
     "Large balances: spread across several banks, use different ownership categories, use a sweep network like IntraFi, or hold Treasury bills (backed by the U.S. government).",
     "Fintech apps: FDIC 'pass-through' coverage protects you if the partner bank fails, not if the app company itself fails or loses records."],
    ["$250,000 per depositor, per bank, per ownership category (FDIC); the same limit at credit unions (NCUA).",
     "SIPC: up to $500,000 per customer, including a $250,000 limit for cash (SIPC).",
     "About 94% of Silicon Valley Bank's deposits were uninsured when it failed in March 2023 (Federal Reserve review)."],
    ["After SVB and Signature Bank failed in March 2023, regulators used a 'systemic risk exception' to protect even uninsured deposits, but they warned that this isn't guaranteed next time.",
     "When fintech middleman Synapse went bankrupt in 2024, thousands of customers of apps that used it couldn't access their money for months because records didn't match, a gap FDIC insurance doesn't cover (FDIC and CFPB statements)."],
    ["FDIC insures depositors against bank failure, not investors against market losses.", "The limit is per bank, so two accounts at the same bank in the same category share one $250,000 limit."],
    "\"Up to $250,000 per depositor at each FDIC-insured bank is backed by the U.S. government, and no one has lost a penny of insured deposits since 1934.\"",
    [("Our client just received $600,000 from selling a house. How do we keep it safe?",
      "We'd make sure every dollar is insured or government-backed. The FDIC covers $250,000 per depositor, per bank, per ownership category, so we could split it across three banks, or use joint accounts and a sweep network like IntraFi that spreads deposits automatically. Money not needed for a year could go into Treasury bills, which are backed by the U.S. government. When Silicon Valley Bank failed, 94% of its deposits were over the limit, which is exactly the risk we're removing."),
     ("Is the money in my Cash App or Venmo account insured?",
      "Only partly, and only in certain cases. Many apps hold money at a partner bank with FDIC pass-through coverage, which protects you if that bank fails, but not if the app company itself fails. When Synapse collapsed in 2024, customers of several apps were locked out for months. We'd keep the emergency fund at an FDIC-insured bank and use payment apps only for moving money."),
     ("If I buy a mutual fund at my bank, is it FDIC-insured?",
      "No. FDIC coverage applies only to deposits like checking, savings and CDs. A mutual fund can lose value even if you bought it at a bank branch. That's normal for investments, so we'd only put money there that you won't need for five or more years.")],
    [FDIC, NCUA, SIPC])

sub("payments", "Payments, checking accounts and online banking", ["FI:058", "FI:560", "FI:070", "FI:565", "FI:830"],
    ["Payments move through a few rails. Card networks (Visa, Mastercard) carry debit and credit card purchases. The ACH network carries direct deposits, bill payments and transfers in batches, usually same day or next day. Wires (Fedwire) move large amounts in final, same-day transfers. Instant payment systems, The Clearing House's RTP network (2017) and the Fed's FedNow (2023), settle in seconds, 24/7. Apps like Zelle, Venmo and Cash App sit on top of these rails.",
     "Managing an account well means paying bills on time (autopay for fixed bills), writing a check correctly when one is needed, and reconciling, or balancing, the account each month so your records match the bank's. Online accounts add security work: strong unique passwords, multifactor authentication, alerts and regular statement checks. Federal law limits your loss on unauthorized electronic transfers only if you report quickly."],
    ["Writing a check: date, payee, amount in numbers and in words, signature, memo. Draw a line after the written amount so no one can add to it.",
     "Balancing: start with the bank statement balance, add deposits in transit, subtract outstanding checks; it should equal your register balance after adding interest and subtracting fees.",
     "Bill pay: autopay for fixed bills, calendar reminders for variable ones; pay credit cards in full by the due date.",
     "Regulation E (debit and electronic transfers): report within 2 business days and your loss is capped at $50; within 60 days, $500; after that, it can be unlimited.",
     "Credit cards: the Fair Credit Billing Act caps liability at $50, and the major networks offer $0 liability."],
    ["ACH processed 33.6 billion payments worth $86.2 trillion in 2024 (Nacha).",
     "Zelle users sent more than $1 trillion in 2024 (Early Warning Services, Zelle's operator).",
     "The Fed launched FedNow in July 2023; payments settle in seconds, any time of day."],
    ["Zelle payments are like cash: if you're tricked into sending money to a scammer, getting it back is hard, so banks tell customers to send only to people they know.",
     "Most U.S. workers are paid by direct deposit through ACH, and the federal government is phasing out paper checks for its payments."],
    ["Reconciling means matching your records to the bank statement, not just checking the balance.", "Debit card fraud can drain your actual cash; credit card fraud uses the bank's money while it's disputed."],
    "\"We'd set up autopay for the fixed bills and alerts on every transaction over $50, so nothing is missed and fraud is caught in minutes, not months.\"",
    [("How often should our client check their accounts?",
      "At least weekly, plus real-time alerts. Federal Regulation E caps losses on an unauthorized debit transaction at $50 only if it's reported within two business days, and the cap rises to $500 after that. A two-minute weekly check in the banking app, plus a full reconciliation each month against the statement, catches errors and fraud early. That habit protects the money we're working to grow."),
     ("Should our client use a debit card or a credit card for everyday spending?",
      "A credit card, if they pay it in full every month. Credit cards have stronger fraud protection, $0 liability at the major networks, and the bank's money is at risk while a dispute is resolved, not theirs. On-time payments also build the credit score they'll need for a car or apartment. If they're likely to carry a balance at today's 22% APR, debit is the safer choice until the habit is solid.")],
    [NACHA, CFPB, FED])

